type Copy = Dictionary & typeof extraCopy.en;
const I18nContext = createContext<{ language: Language; setLanguage: (language: Language) => void; t: Copy }>({ language: 'en', setLanguage: () => undefined, t: { ...dictionaries.en, ...reportLabelsEn, ...extraCopy.en } as Copy });

export function I18nProvider({ children }: Readonly<{ children: React.ReactNode }>) {
  const [language, setLanguage] = useState<Language>('en');
  const t = (language === 'te'
    ? { ...dictionaries.en, ...reportLabelsEn, ...dictionaries.te, ...teluguFinance, ...extraCopy.te, valuesServer: 'ఈరోజు ఫార్మ్ పనిని నమోదు చేయండి; మీ రికార్డులను తాజాగా ఉంచుతాము.' }
    : { ...dictionaries.en, ...reportLabelsEn, ...extraCopy.en, valuesServer: 'Record today’s farm work here so your records stay up to date.' }) as Copy;
  return <I18nContext.Provider value={{ language, setLanguage, t }}>{children}</I18nContext.Provider>;
}
export function useI18n() { return useContext(I18nContext); }
